#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$REPO_ROOT"

PAGES_PROJECT="keaches-songs"

banner "Songs of @keaches — GitHub + Cloudflare setup"

# ── Stage 1: GitHub repository ────────────────────────────────────────────
stage "GitHub — create the repository"
say "The repo is ready locally; we'll create it on GitHub and push."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  note "gh is signed in as $(gh api user --jq .login 2>/dev/null || echo '?')"
else
  open_url "https://cli.github.com/"
  warn "The GitHub CLI (gh) isn't installed or signed in."
  step "Install gh, then run: gh auth login"
  pause "Press Enter once 'gh auth status' succeeds…"
fi

REPO_NAME="${REPO_NAME:-keaches-songs}"
ask REPO_NAME "Repository name [keaches-songs]:"
[[ -z "$REPO_NAME" ]] && REPO_NAME="keaches-songs"

VISIBILITY="--private"
if confirm "Make the repository public? (No = private)"; then
  VISIBILITY="--public"
fi

if git remote get-url origin >/dev/null 2>&1; then
  say "origin already configured: $(git remote get-url origin)"
  if confirm "Push the current branch to origin now?"; then
    git push -u origin HEAD || warn "push failed — push manually once gh is ready"
  fi
else
  if confirm "Create '$REPO_NAME' on GitHub and push?"; then
    gh repo create "$REPO_NAME" "$VISIBILITY" --source=. --remote=origin --push \
      || warn "could not create the repo — create it on GitHub and push manually"
  fi
fi

REPO_SLUG=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || echo "")

# ── Stage 2: Monid API key ────────────────────────────────────────────────
stage "Monid — API key"
say "The daily job calls Monid to fetch reels, so CI needs an API key."
note "This machine already has one; you can reuse it instead of making a new one."

DETECTED_KEY=""
if [[ -f "$HOME/.config/monid/credentials.yaml" ]]; then
  DETECTED_KEY=$(awk '/^[[:space:]]+key:/{print $2; exit}' \
    "$HOME/.config/monid/credentials.yaml" 2>/dev/null || true)
fi

if [[ -n "$DETECTED_KEY" ]]; then
  step "Press Enter to reuse the key already on this machine (${DETECTED_KEY:0:12}…)"
else
  open_url "https://app.monid.ai/access/api-keys"
  step "Copy an API key (starts with monid_)."
fi

printf '  %sMonid API key:%s ' "$BOLD" "$RESET"
read -rs MONID_API_KEY || true
printf '\n'
[[ -z "$MONID_API_KEY" && -n "$DETECTED_KEY" ]] && MONID_API_KEY="$DETECTED_KEY"

if [[ -z "$MONID_API_KEY" ]]; then
  warn "no key entered — set MONID_API_KEY later with: gh secret set MONID_API_KEY"
else
  set_secret MONID_API_KEY "$MONID_API_KEY"
fi

# ── Stage 3: Cloudflare account ID ────────────────────────────────────────
stage "Cloudflare — account ID"
say "Both the CI deploy and the Pages project need your Cloudflare account ID."
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Press CMD/CTRL+K, type 'Copy account ID', press Enter — it's on your clipboard."
step "Or: Workers & Pages → Account Details → Account ID → copy."
ask CLOUDFLARE_ACCOUNT_ID "Cloudflare account ID:"
if [[ -n "$CLOUDFLARE_ACCOUNT_ID" ]]; then
  set_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
else
  warn "no account ID entered — set CLOUDFLARE_ACCOUNT_ID later"
fi

# ── Stage 4: Cloudflare API token + Pages project ─────────────────────────
stage "Cloudflare — API token"
say "Create a token that is allowed to deploy to Cloudflare Pages."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Select 'Create Token' → 'Create Custom Token'."
step "Permissions: Account · Cloudflare Pages · Edit."
step "Account Resources: Include · your account. Then Continue → Create Token."
step "Copy the token (shown only once; it starts with cfut_)."
ask_secret CLOUDFLARE_API_TOKEN "Cloudflare API token:"
if [[ -n "$CLOUDFLARE_API_TOKEN" ]]; then
  set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
else
  warn "no token entered — set CLOUDFLARE_API_TOKEN later"
fi

say "Now we'll make sure the Pages project '$PAGES_PROJECT' exists, so the first"
say "CI deploy has somewhere to go."
BRANCH=$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo main)
if [[ -n "$CLOUDFLARE_API_TOKEN" && -n "$CLOUDFLARE_ACCOUNT_ID" ]] && command -v npx >/dev/null 2>&1; then
  if confirm "Create the Pages project '$PAGES_PROJECT' now (production branch: $BRANCH)?"; then
    if CLOUDFLARE_API_TOKEN="$CLOUDFLARE_API_TOKEN" \
       CLOUDFLARE_ACCOUNT_ID="$CLOUDFLARE_ACCOUNT_ID" \
       npx --yes wrangler@latest pages project create "$PAGES_PROJECT" \
         --production-branch="$BRANCH" >/dev/null 2>&1; then
      printf '  %s✓ created%s Pages project %s\n' "$GREEN" "$RESET" "$PAGES_PROJECT"
    else
      warn "could not create it (it may already exist) — the first deploy can also create it"
    fi
  fi
else
  warn "skipping project creation — the first deploy will create it automatically"
fi

# ── Stage 5: first run ────────────────────────────────────────────────────
stage "First run"
say "The archive is already seeded and committed, so this run is a smoke test:"
say "it fetches reels, rebuilds the page and deploys — with no new downloads."
if [[ -n "$REPO_SLUG" ]]; then
  open_url "https://github.com/$REPO_SLUG/actions"
else
  note "Open your repository's Actions tab."
fi
step "Select 'Update songs' → 'Run workflow' → mode: update → Run."
if [[ -n "$REPO_SLUG" ]] && command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  if confirm "Trigger the workflow now with gh?"; then
    if gh workflow run daily.yml --repo "$REPO_SLUG" -f mode=update; then
      say "Watch it with: gh run watch --repo $REPO_SLUG"
    else
      warn "couldn't trigger it — use the Actions tab instead"
    fi
  fi
fi

finish
